const fs = require("fs");
const cp = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
fs.mkdirSync("/tmp/proj", { recursive: true });
fs.writeFileSync("/tmp/proj/index.js", "export default { fetch() { return new Response('hello'); } };\n");
fs.writeFileSync("/tmp/proj/wrangler.toml", 'name = "t"\nmain = "index.js"\ncompatibility_date = "2025-01-01"\n');
const out = "/tmp/proj/out.ndjson";
const r = cp.spawnSync("node", ["/w/node_modules/wrangler/bin/wrangler.js", "deploy", "--dry-run", "--outdir", "dist"], { cwd: "/tmp/proj", encoding: "utf8", timeout: 80000, env: Object.assign({}, process.env, { WRANGLER_OUTPUT_FILE_PATH: out, WRANGLER_SEND_METRICS: "false", CI: "true" }) });
if (r.status !== 0 || !fs.existsSync(out)) broken("dry-run deploy failed: " + r.status + " " + (r.stderr || "").slice(0, 300));
const recs = fs.readFileSync(out, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
const dep = recs.find((x) => x.type === "deploy");
if (!dep) broken("no deploy record in output");
if (!dep.bundle_size) symptom("deploy output record has no bundle_size");
if (!(dep.bundle_size.raw_bytes > 0) || !(dep.bundle_size.gzip_bytes > 0)) broken("bad bundle_size " + JSON.stringify(dep.bundle_size));
console.log("OK: bundle_size " + JSON.stringify(dep.bundle_size));

